const input = $input.first().json;
const body = input.body || input;
const { nombre, apellido, whatsapp, email, telefono, lead_tipo, origen, categoria, nivel, objetivo, resumen, disponibilidad, tags, primer_contacto, person_identifier } = body;

if (!nombre || !whatsapp) {
  throw new Error('Faltan campos requeridos: nombre, whatsapp');
}

const nom = String(nombre).replace(/'/g, "''");
const ap = apellido && apellido !== 'Sin definir' ? String(apellido).replace(/'/g, "''") : null;
const res = resumen && resumen !== 'Sin definir' ? String(resumen).replace(/'/g, "''") : null;
const obj = objetivo && objetivo !== 'Sin definir' ? String(objetivo).replace(/'/g, "''") : null;
const dis = disponibilidad && disponibilidad !== 'Sin definir' ? String(disponibilidad).replace(/'/g, "''") : null;
const pi = person_identifier ? String(person_identifier).replace(/'/g, "''") : nom; // Fallback: usar nombre
const primerContactoVal = primer_contacto && primer_contacto !== 'Sin definir' && primer_contacto !== '' ? 'CURRENT_TIMESTAMP' : 'CURRENT_TIMESTAMP';
const validCategories = ['KIDS', 'ADULTO', 'ADOLESCENTE', 'PERSONALIZADO'];
const catVal = categoria && validCategories.includes(categoria) ? categoria : (lead_tipo || 'PERSONALIZADO');

const query = `INSERT INTO leads (nombre, apellido, whatsapp, email, telefono, lead_tipo, origen, categoria, nivel, objetivo, resumen, disponibilidad, tags, person_identifier, estado, estado_motivo, estado_fecha, primer_contacto, ultimo_contacto, created_at, updated_at)
VALUES ('${nom}', ${ap ? `'${ap}'` : 'null'}, '${whatsapp}', ${email ? `'${email}'` : 'null'}, ${telefono ? `'${telefono}'` : 'null'}, ${lead_tipo ? `'${lead_tipo}'` : 'null'}, ${origen ? `'${origen}'` : 'null'}, '${catVal}', ${nivel ? `'${nivel}'` : 'null'}, ${obj ? `'${obj}'` : 'null'}, ${res ? `'${res}'` : 'null'}, ${dis ? `'${dis}'` : 'null'}, ${tags ? `'${tags}'` : 'null'}, '${pi}', 'NUEVO', 'Nuevo contacto', CURRENT_TIMESTAMP, ${primerContactoVal}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
RETURNING id, nombre, whatsapp, email, person_identifier, lead_tipo, origen, nivel, estado, created_at;`;

return [{json: {query}}];
